import {EasterEggView} from '../../src/features/easter-egg.ts';import {easterEgg} from '../../src/platform/easter-egg.ts';import {emptyEggStats,type EggStats} from '../../src/domain/easter-egg.ts';
export function createEggFixture(failAudio=false){let stats:EggStats=emptyEggStats(),saves=0,homes=0,audioCalls=0,opened:string[]=[];const host=document.querySelector<HTMLElement>('#app')!,view=new EasterEggView({load:()=>structuredClone(stats),save:value=>{stats=structuredClone(value);saves++;},audio:signal=>{audioCalls++;return failAudio?Promise.resolve({ok:false}):easterEgg.audio(signal);},home:()=>{homes++;},open:async url=>{opened.push(url);}},true);view.mount(host);return {failAudio:(value:boolean)=>failAudio=value,state:()=>({ready:view.isReady,running:view.isRunning,stage:view.confirmationStage,stats,saves,homes,audioCalls,opened,diagnostic:view.diagnostic}),probe:()=>view.probeNetwork(location.origin+'/egg-network-probe'),inspect:(id:string)=>view.inspect(id),run:(id:string)=>view.testRun(id),stop:()=>view.stop(),back:()=>view.back(),background:()=>view.background(),remount:()=>view.mount(host)};}
